{% extends "base.html" %}

{% block title %}Meus Empréstimos - Biblioteca Digital{% endblock %}

{% block content %}
<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.5rem;">
  <h2>Meus Empréstimos</h2>
  <a href="{{ url_for('index') }}" class="btn btn-outline">+ Buscar Mais Livros</a>
</div>

{% if is_blocked %}
  <div class="alert alert-danger">
    <strong>Atenção:</strong> Seu cadastro está temporariamente bloqueado para novos empréstimos devido a atrasos. Favor devolver seus livros pendentes para regularização.
  </div>
{% endif %}

{% if loans %}
  <div class="card">
    <div class="table-responsive">
      <table>
        <thead>
          <tr>
            <th>Livro</th>
            <th>Gênero</th>
            <th>Data de Empréstimo</th>
            <th>Data Limite (Prazo)</th>
            <th>Status</th>
            <th>Ações</th>
          </tr>
        </thead>
        <tbody>
          {% for loan in loans %}
            {% set is_overdue = (loan.status == 'active' and loan.due_date < today) %}
            <tr style="{% if is_overdue %}background-color: #fef2f2;{% endif %}">
              <td>
                <strong>{{ loan.title }}</strong><br>
                <small style="color: var(--gray-500);">{{ loan.author }}</small>
              </td>
              <td>{{ loan.category }}</td>
              <td>{{ loan.loan_date }}</td>
              <td>
                <span style="font-weight: 600; {% if is_overdue %}color: var(--danger);{% endif %}">
                  {{ loan.due_date }}
                </span>
                {% if is_overdue %}
                  <br><small style="color: var(--danger); font-weight: bold;">(Em Atraso!)</small>
                {% endif %}
              </td>
              <td>
                {% if loan.status == 'returned' %}
                  <span class="badge badge-secondary">Devolvido em {{ loan.return_date }}</span>
                {% elif is_overdue %}
                  <span class="badge badge-danger">Atrasado</span>
                {% else %}
                  <span class="badge badge-success">No Prazo</span>
                {% endif %}
              </td>
              <td>
                {% if loan.status == 'active' %}
                  <form action="{{ url_for('return_book', loan_id=loan.id) }}" method="POST">
                    <button type="submit" class="btn btn-sm btn-primary">Devolver Livro</button>
                  </form>
                {% else %}
