  <div class="card" style="text-align: center; padding: 3rem;">
    <h3>Você ainda não possui nenhum empréstimo</h3>
    <p style="color: var(--gray-500); margin-top: 0.5rem;">Explore o catálogo e escolha o seu próximo livro!</p>
    <a href="{{ url_for('index') }}" class="btn btn-primary" style="margin-top: 1rem;">Explorar Acervo</a>
  </div>
{% endif %}
{% endblock %}
