    </div>

    <div class="form-group">
      <label for="author">Autor: *</label>
      <input type="text" id="author" name="author" value="{{ book.author if book else '' }}" class="form-control" required placeholder="Ex: Machado de Assis">
    </div>

    <div style="display: flex; gap: 1rem; flex-wrap: wrap;">
      <div class="form-group" style="flex: 1; min-width: 200px;">
        <label for="category">Gênero / Categoria:</label>
