        <small style="color: var(--gray-500);">Atualmente emprestados: {{ book.total_copies - book.available_copies }}</small>
      {% endif %}
    </div>

    <div class="form-group">
      <label for="description">Sinopse / Descrição:</label>
      <textarea id="description" name="description" class="form-control" rows="4" placeholder="Breve resumo da obra...">{{ book.description if book else '' }}</textarea>
    </div>

    <div style="display: flex; gap: 0.8rem; margin-top: 1.5rem;">
      <button type="submit" class="btn btn-success" style="flex: 1;">
