{% extends "base.html" %}

{% block title %}Controle de Leitores - Bibliotecário{% endblock %}

{% block content %}
<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.5rem;">
  <h2>Controle de Leitores e Bloqueios</h2>
</div>

<div class="card">
  <div class="table-responsive">
    <table>
      <thead>
        <tr>
          <th>Nome</th>
          <th>E-mail</th>
          <th>Livros Emprestados</th>
          <th>Livros em Atraso</th>
          <th>Situação</th>
          <th>Ações de Bloqueio</th>
        </tr>
      </thead>
      <tbody>
        {% for reader in readers %}
          <tr style="{% if reader.overdue_loans_count > 0 %}background-color: #fef2f2;{% endif %}">
            <td><strong>{{ reader.name }}</strong></td>
            <td>{{ reader.email }}</td>
            <td>
              <span class="badge badge-secondary">{{ reader.active_loans_count }} ativos</span>
            </td>
            <td>
              {% if reader.overdue_loans_count > 0 %}
                <span class="badge badge-danger">{{ reader.overdue_loans_count }} livro(s) em atraso!</span>
              {% else %}
                <span style="color: var(--success); font-weight: 500;">Nenhum</span>
              {% endif %}
            </td>
            <td>
              {% if reader.is_blocked %}
                <span class="badge badge-danger">🚫 Bloqueado</span>
              {% else %}
                <span class="badge badge-success">✅ Liberado</span>
              {% endif %}
            </td>
            <td>
              <form action="{{ url_for('toggle_user_block', user_id=reader.id) }}" method="POST">
                {% if reader.is_blocked %}
                  <button type="submit" class="btn btn-sm btn-success">Desbloquear Leitor</button>
                {% else %}
                  <button type="submit" class="btn btn-sm btn-danger" onclick="return confirm('Deseja realmente bloquear este leitor para novos empréstimos?');">
                    Bloquear Novos Empréstimos
                  </button>
                {% endif %}
              </form>
            </td>
          </tr>
        {% else %}
          <tr>
            <td colspan="6" style="text-align: center; padding: 2rem;">Nenhum leitor cadastrado até o momento.</td>
          </tr>
        {% endfor %}
      </tbody>
    </table>
  </div>
</div>
{% endblock %}
